import {createStudy,canvasSurface,seededRandom,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:6,title:'Type Force',category:'Typography / Physics',accent:'#ec482e',background:'#eeeade',foreground:'#151713'});
const canvas=document.querySelector('#force-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
const input=document.querySelector('#force-word'),strength=document.querySelector('#force-strength');
let letters=[],fontSize=180,word='TYPE FORCE',pointer={x:-999,y:-999,active:false},lastWidth=0,lastHeight=0;
function layout(){const {ctx,width:w,height:h}=surface;lastWidth=w;lastHeight=h;const words=word.trim().toUpperCase().split(/\s+/).filter(Boolean);let lines=words.length>1?[words.slice(0,Math.ceil(words.length/2)).join(' '),words.slice(Math.ceil(words.length/2)).join(' ')]:[words[0]||'TYPE'];fontSize=Math.min(w*.29,h*.29);ctx.font=`700 ${fontSize}px Display, sans-serif`;const widest=Math.max(...lines.map(line=>ctx.measureText(line).width));fontSize*=Math.min(1,(w-50)/Math.max(1,widest));ctx.font=`700 ${fontSize}px Display, sans-serif`;letters=[];const totalHeight=fontSize*.89*lines.length;const middleY=h*.48-(w<650?28:0);lines.forEach((line,row)=>{const width=ctx.measureText(line).width;let x=(w-width)/2;const baseline=middleY-totalHeight/2+fontSize*.75+row*fontSize*.91;for(const char of line){const width=ctx.measureText(char).width;letters.push({char,bx:x,by:baseline,x,y:baseline,vx:0,vy:0,w:width,row});x+=width}})}
function draw({dt=0,time=0}={}){if(lastWidth!==surface.width||lastHeight!==surface.height)layout();const {ctx,width:w,height:h}=surface;ctx.clearRect(0,0,w,h);ctx.fillStyle='#eeeade';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#1517130d';ctx.lineWidth=1;for(let x=30;x<w;x+=52){ctx.beginPath();ctx.moveTo(x,140);ctx.lineTo(x,h-160);ctx.stroke()}ctx.font=`700 ${fontSize}px Display, sans-serif`;ctx.textBaseline='alphabetic';const running=study.running();const step=running?Math.min(dt,.032):0;for(const p of letters){if(step){const dx=p.x+p.w/2-pointer.x,dy=p.y-fontSize*.35-pointer.y,d=Math.hypot(dx,dy)||1;let ax=(p.bx-p.x)*30,ay=(p.by-p.y)*30;if(pointer.active&&d<175){const force=(1-d/175)*Number(strength.value)*22;ax+=dx/d*force;ay+=dy/d*force}p.vx=(p.vx+ax*step)*Math.exp(-8*step);p.vy=(p.vy+ay*step)*Math.exp(-8*step);p.x+=p.vx*step;p.y+=p.vy*step}ctx.save();ctx.translate(p.x+p.w/2,p.y);ctx.rotate(clamp(p.vx*.0002,-.15,.15));ctx.fillStyle=p.row%2?'#ec482e':'#151713';ctx.fillText(p.char,-p.w/2,0);ctx.restore()}if(pointer.active){ctx.strokeStyle='#ec482e';ctx.lineWidth=1;ctx.beginPath();ctx.arc(pointer.x,pointer.y,12,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(pointer.x-20,pointer.y);ctx.lineTo(pointer.x+20,pointer.y);ctx.moveTo(pointer.x,pointer.y-20);ctx.lineTo(pointer.x,pointer.y+20);ctx.stroke()}}
const move=event=>{const r=canvas.getBoundingClientRect();pointer={x:event.clientX-r.left,y:event.clientY-r.top,active:true};document.querySelector('#force-coordinate').textContent=`X ${Math.round(pointer.x).toString().padStart(3,'0')} / Y ${Math.round(pointer.y).toString().padStart(3,'0')}`;if(!study.running())study.invalidate()};
canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerleave',()=>pointer.active=false);
input.addEventListener('input',()=>{word=input.value||'TYPE';canvas.setAttribute('aria-label',`${word}: individual letterforms with spring motion.`);layout();study.invalidate()});
strength.addEventListener('input',()=>document.querySelector('#force-value').textContent=strength.value);
document.querySelector('#force-impulse').addEventListener('click',()=>{if(!study.running()){study.invalidate();return}const random=seededRandom(61);for(const p of letters){p.vx+=(random()-.5)*1600;p.vy+=(random()-.5)*1200}study.invalidate()});
study.onResize(()=>{surface.resize();layout();study.invalidate()});study.onFrame(draw);study.onMotion(running=>{if(!running){letters.forEach(p=>{p.x=p.bx;p.y=p.by;p.vx=p.vy=0});draw()}});study.setReset(()=>{input.value=word='TYPE FORCE';strength.value='70';document.querySelector('#force-value').textContent='70';pointer={x:-999,y:-999,active:false};document.querySelector('#force-coordinate').textContent='X — / Y —';canvas.setAttribute('aria-label','TYPE FORCE: large individual letterforms respond to the pointer with spring motion.');layout();study.invalidate()});study.setExport(()=>downloadCanvas(canvas,'06-type-force.png'));study.cleanup(()=>surface.dispose());document.fonts.load('700 100px Display').then(()=>{layout();study.invalidate()});
